r=Path('native/client/assets/first-slice');o=r/'starter-projection/weapon-source';o.mkdir(exist_ok=True);src=r/'starter-combat/originals/male-attack-front-0-3-imagegen-v1.png';im=Image.open(src).convert('RGBA');box=[120,287,194,315];patch=im.crop(box);patch.save(o/'painted-branch-patch.png');a=np.array(patch);valid=a[:,:,3]>=128;rgb=np.median(a[:,:,:3][valid],axis=0)/255;linear=np.where(rgb<=.04045,rgb/12.92,((rgb+.055)/1.055)**2.4);report={'source':str(src),'source_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'crop':box,'region':'Isolated wooden branch in first attack pose, excluding hand','foreground_samples':int(valid.sum()),'fallback_linear_rgb':linear.tolist(),'method':'ImageGen wood texture patch; texture alpha controls confidence only; original club mesh supplies final alpha','patch':'painted-branch-patch.png','patch_sha256':hashlib.sha256((o/'painted-branch-patch.png').read_bytes()).hexdigest()};(o/'provenance.json').write_text(json.dumps(report,indent=2));bg=Image.new('RGBA',patch.size,(38,45,40,255));bg.alpha_composite(patch);bg.resize((592,224),Image.Resampling.NEAREST).save(o/'patch-inspection.png');print(report)
